package game.world;

import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import tools.jackson.databind.json.JsonMapper;

/** Jurisdiction, crime and death-time entitlement. Never awards on a kill. */
@Service
public class LawService {
 private final JdbcTemplate db;private final SceneService scenes;private WorldMap world;
 private final JsonMapper json=JsonMapper.builder().build();
 public record Claim(UUID stationId,UUID corpseId,UUID requestId) {}
 LawService(JdbcTemplate db,SceneService scenes){this.db=db;this.scenes=scenes;}
 public void initialize(WorldMap world){this.world=world;db.update("insert into factions values('qingyu','青屿') on conflict do nothing");if(db.queryForObject("select count(*) from jurisdiction where world_version=?",Integer.class,world.version())==0)for(var t:world.tiles())if(t.walkable())db.update("insert into jurisdiction values(?,?,?,'qingyu',?)",world.version(),t.q(),t.r(),t.place()!=null&&Set.of("town","village").contains(t.place().type()));}
 private Map<String,Object> profile(UUID a){return db.queryForMap("select c.*,coalesce(a.q,c.q) as world_q,coalesce(a.r,c.r) as world_r from characters c left join accounts a on a.id=c.id where c.id=?",a);}
 private Set<String> factions(UUID a,boolean enforced){var c=profile(a);return new HashSet<>(db.queryForList("select faction_id from jurisdiction where world_version=? and q=? and r=?"+(enforced?" and enforced":""),String.class,world.version(),c.get("world_q"),c.get("world_r")));}
 public boolean wanted(UUID a,String f){return db.queryForObject("select exists(select 1 from crimes where actor=? and faction_id=? and cleared_at is null)",Boolean.class,a,f);}
 public List<String> marks(UUID a){var out=new ArrayList<String>();for(var f:factions(a,false))if(wanted(a,f))out.add(f);return out;}
 public String displayName(UUID a,String name){return marks(a).isEmpty()?name:name+" · 通缉";}
 public List<UUID> respawn(long now){var revived=new ArrayList<UUID>();for(var s:db.queryForList("select s.* from law_stations s join characters c on c.id=s.officer_id where c.life='dead' and c.timer_end<=?",now)){UUID actor=(UUID)s.get("officer_id"),scene=(UUID)s.get("scene_id");var map=json.readValue(db.queryForObject("select document from scene_documents where id=?",String.class,scene),SceneMap.class);var occupied=new HashSet<>(db.query("select p.q,p.r from scene_positions p join characters c on c.id=p.character_id where p.scene_id=? and p.active and c.life in ('alive','down')",(r,n)->new WorldMap.Hex(r.getInt(1),r.getInt(2)),scene));var cell=TownService.landing(map,new WorldMap.Hex(((Number)s.get("board_q")).intValue(),((Number)s.get("board_r")).intValue()),occupied);if(cell==null)continue;db.update("update characters set life='alive',hp=max_hp,down_hp=max_down_hp,timer_kind=null,timer_end=0 where id=?",actor);db.update("update scene_positions set active=false where character_id=?",actor);db.update("insert into scene_positions values(?,?,?,?,true) on conflict(character_id,scene_id) do update set q=excluded.q,r=excluded.r,active=true",actor,scene,cell.q(),cell.r());revived.add(actor);}return revived;}
 public boolean advance(long now){boolean changed=false;for(var row:db.queryForList("select distinct actor from crimes where cleared_at is null")){UUID a=(UUID)row.get("actor");var inside=factions(a,false);for(var crime:db.queryForList("select id,faction_id,left_at from crimes where actor=? and cleared_at is null",a)){if(inside.contains(crime.get("faction_id"))){if(crime.get("left_at")!=null){db.update("update crimes set left_at=null where id=?",crime.get("id"));changed=true;}}else if(crime.get("left_at")==null){db.update("update crimes set left_at=? where id=?",now,crime.get("id"));changed=true;}else if(now-((Number)crime.get("left_at")).longValue()>=1800000){db.update("update crimes set cleared_at=? where id=?",now,crime.get("id"));changed=true;}}}return changed;}
 public void hostile(UUID actor,UUID target,String reason,long now){if(actor.equals(target))return;advance(now);var regions=factions(actor,true);if(regions.isEmpty())return;var t=profile(target);if(Boolean.TRUE.equals(t.get("malicious"))||Set.of("rabbit","deer").contains(Objects.toString(t.get("species"),"")))return;if(regions.stream().anyMatch(f->wanted(target,f)))return;
  // Self-defence against an actual aggressor is legal; beginning a battle alone is not aggression.
  if(db.queryForObject("select exists(select 1 from battle_events e join battle_encounters b on b.id=e.encounter_id where b.active and e.actor_id=? and e.target_id=? and e.kind in ('attack','interrupt'))",Boolean.class,target,actor)&&!regions.stream().anyMatch(f->wanted(actor,f)))return;
  for(String f:regions)db.update("insert into crimes(actor,faction_id,reason,created_at) values(?,?,?,?)",actor,f,reason,now);
 }
 public void aid(UUID actor,UUID target,long now){if(actor.equals(target))return;var regions=factions(actor,true);if(regions.isEmpty())return;boolean dangerous=Boolean.TRUE.equals(profile(target).get("malicious"))||regions.stream().anyMatch(f->wanted(target,f));if(!dangerous)return;var opponents=db.queryForList("select distinct e.actor_id from battle_events e join battle_encounters b on b.id=e.encounter_id where b.active and e.target_id=? and e.actor_id<>? and e.kind in ('attack','interrupt')",UUID.class,target,actor);boolean fighting=opponents.stream().anyMatch(id->!Boolean.TRUE.equals(profile(id).get("malicious"))&&regions.stream().noneMatch(f->wanted(id,f)));if(fighting)for(String f:regions)db.update("insert into crimes(actor,faction_id,reason,created_at) values(?,?,'战斗中援助通缉或恶意目标',?)",actor,f,now);}
 public void snapshot(UUID corpse,UUID actor,long now){advance(now);for(var row:db.queryForList("select faction_id,array_agg(id) as ids from crimes where actor=? and cleared_at is null group by faction_id",actor)){String f=(String)row.get("faction_id");db.update("insert into corpse_bounties(corpse_id,faction_id,actor,crime_ids) select ?,?, ?,array_agg(id) from crimes where actor=? and faction_id=? and cleared_at is null",corpse,f,actor,actor,f);}}
 public void ensureStation(SceneMap map){if(world==null||map.level()!=2)return;var factions=db.queryForList("select faction_id from jurisdiction where world_version=? and q=? and r=? and enforced order by faction_id",String.class,map.worldVersion(),map.owner().q(),map.owner().r());for(String faction:factions){if(db.queryForObject("select exists(select 1 from law_stations where scene_id=? and faction_id=?)",Boolean.class,map.id(),faction))continue;
   var blocked=new HashSet<>(db.query("select q,r from scene_objects where scene_id=? union select q,r from scene_positions where scene_id=? and active union select board_q,board_r from law_stations where scene_id=?",(r,n)->new WorldMap.Hex(r.getInt(1),r.getInt(2)),map.id(),map.id(),map.id()));WorldMap.Hex seat=null,board=null;
   for(var c:map.cells()){if(!c.walkable()||blocked.contains(c.hex())||WorldMap.distance(new WorldMap.Hex(0,0),c.hex())>=map.radius()-2)continue;var next=c.hex().neighbors().stream().filter(h->!blocked.contains(h)&&map.cells().stream().anyMatch(x->x.hex().equals(h)&&x.walkable())).findFirst();if(next.isPresent()){seat=c.hex();board=next.get();break;}}if(seat==null)return;
   UUID officer=UUID.nameUUIDFromBytes((map.id()+":"+faction+":officer").getBytes(java.nio.charset.StandardCharsets.UTF_8));db.update("insert into characters(id,kind,species,name,q,r,bind_q,bind_r,next_move) values(?,'service','officer','执法人员',?,?,?,?,?) on conflict(id) do nothing",officer,map.owner().q(),map.owner().r(),map.owner().q(),map.owner().r(),Long.MAX_VALUE);
   db.update("insert into scene_positions(character_id,scene_id,q,r,active) values(?,?,?,?,true) on conflict(character_id,scene_id) do nothing",officer,map.id(),seat.q(),seat.r());db.update("insert into law_stations values(?,?,?,?,?,?)",officer,map.id(),faction,officer,board.q(),board.r());
  }}
 public List<Map<String,Object>> stations(UUID actor){return db.queryForList("select s.*,f.name as faction_name,c.life,p.q,p.r from scene_positions own join law_stations s on s.scene_id=own.scene_id join factions f on f.id=s.faction_id join characters c on c.id=s.officer_id left join scene_positions p on p.character_id=c.id and p.active and p.scene_id=s.scene_id where own.character_id=? and own.active",actor);}
 private Map<String,Object> station(UUID actor,UUID station,boolean board){var own=db.queryForList("select * from scene_positions where character_id=? and active",actor);var s=stations(actor).stream().filter(x->x.get("id").equals(station)).findFirst().orElseThrow(()->AccountService.bad("不在该执法设施场景"));if(own.isEmpty())throw AccountService.bad("请进入场景");var p=own.getFirst();Object q=s.get(board?"board_q":"q"),r=s.get(board?"board_r":"r");if(q==null||WorldMap.distance(new WorldMap.Hex(((Number)p.get("q")).intValue(),((Number)p.get("r")).intValue()),new WorldMap.Hex(((Number)q).intValue(),((Number)r).intValue()))>1)throw AccountService.bad("请走到互动距离内");if(!board&&(!"alive".equals(s.get("life"))||db.queryForObject("select exists(select 1 from battle_encounters where scene_id=? and active)",Boolean.class,s.get("scene_id"))))throw AccountService.bad("执法人员死亡或本场景战斗中，暂停交尸");return s;}
 public Object board(UUID actor,UUID id,long now){var s=station(actor,id,true);advance(now);return db.queryForList("select c.actor,coalesce(a.username,nullif(p.name,''),'旅人') as name,p.kind,p.species,string_agg(distinct c.reason,'；') as reasons,1 as reward_silver from crimes c join characters p on p.id=c.actor left join accounts a on a.id=p.id where faction_id=? and cleared_at is null group by c.actor,a.username,p.name,p.kind,p.species order by name",s.get("faction_id"));}
 public Object eligible(UUID actor,UUID id){var s=station(actor,id,false);return db.queryForList("select l.id,l.name,b.faction_id,b.reward_silver,cardinality(b.crime_ids) as records from loot_containers l join corpse_bounties b on b.corpse_id=l.id where l.carrier_id=? and b.faction_id=? and not exists(select 1 from loot_items i where i.container_id=l.id and i.quantity>0)",actor,s.get("faction_id"));}
 public Object claim(UUID actor,Claim claim,long now){if(claim==null||claim.requestId()==null)throw AccountService.bad("需要唯一请求编号");String payload=claim.stationId()+":"+claim.corpseId();var old=db.queryForList("select * from transaction_receipts where actor_id=? and request_id=?",actor,claim.requestId());if(!old.isEmpty()){var r=old.getFirst();if(!r.get("kind").equals("bounty")||!payload.equals(r.get("payload")))throw AccountService.bad("请求编号已用于其他交易");return json.readValue((String)r.get("result"),Object.class);}
  if(!"alive".equals(profile(actor).get("life")))throw AccountService.bad("当前无法交尸");var s=station(actor,claim.stationId(),false);var b=db.queryForList("select b.* from corpse_bounties b join loot_containers l on l.id=b.corpse_id where b.corpse_id=? and faction_id=? and l.carrier_id=? for update of l",claim.corpseId(),s.get("faction_id"),actor);if(b.isEmpty())throw AccountService.bad("这具尸体没有本势力领奖资格或不在背包");if(db.queryForObject("select exists(select 1 from handover_corpses where corpse_id=?)",Boolean.class,claim.corpseId()))throw AccountService.bad("尸体已预留给交接，请先取消");if(db.queryForObject("select exists(select 1 from loot_items where container_id=? and quantity>0)",Boolean.class,claim.corpseId()))throw AccountService.bad("请先取空尸体物品");var entitlement=b.getFirst();db.update("update crimes set cleared_at=? where id=any(select unnest(crime_ids) from corpse_bounties where corpse_id=? and faction_id=?) and cleared_at is null",now,claim.corpseId(),s.get("faction_id"));db.update("insert into inventories(character_id,item_code,quantity) values(?,'silver_coin',?) on conflict(character_id,item_code) do update set quantity=inventories.quantity+excluded.quantity",actor,entitlement.get("reward_silver"));db.update("delete from loot_containers where id=?",claim.corpseId());var result=Map.of("message","已交尸领奖，仅清除该势力死亡前记录","silver",entitlement.get("reward_silver"));db.update("insert into transaction_receipts values(?,?,'bounty',?,?,?)",actor,claim.requestId(),payload,json.writeValueAsString(result),now);return result;
 }
}
